import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type FlexBicepGraphProps = Record<string, any>;

const FlexBicepGraph: React.FC<FlexBicepGraphProps> = ({
  backgroundColor = "#f5f5f5",
  transparentBackground = false,
  durationInSeconds = 5,
  skinColor = "#E0AC69",
  outlineColor = "#2c2c2c",
  graphColor = "#2E7D32",
  swellingIntensity = 35,
  iconScale = 1.0,
}) => {
  // We don't strictly need fonts for this graphic-only animation, 
  // but we keep the hook to strictly follow the required structure.
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timing
  // Flex starts at 1s, holds, then releases.
  const flexStartFrame = fps * 1; 
  const flexDuration = fps * 0.8; 
  
  // Create a spring for the "flex" action
  // We want it to go 0 -> 1 -> 0
  
  // Phase 1: Flex In
  const flexIn = spring({
    frame: frame - flexStartFrame,
    fps,
    config: { damping: 12, stiffness: 100, mass: 1 },
    durationInFrames: flexDuration
  });

  // Phase 2: Relax (starts after hold)
  const holdDuration = fps * 0.5;
  const relaxStartFrame = flexStartFrame + flexDuration + holdDuration;
  
  const flexOut = spring({
    frame: frame - relaxStartFrame,
    fps,
    config: { damping: 12, stiffness: 80, mass: 1 },
    durationInFrames: flexDuration
  });

  // Combine springs to get a smooth 0 -> 1 -> 0 curve
  // If flexOut starts, we subtract it from the fully flexed state
  const flexAmount = interpolate(
    frame,
    [0, flexStartFrame, flexStartFrame + flexDuration, relaxStartFrame, relaxStartFrame + flexDuration],
    [0, 0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // We add a little "organic" bounce using the spring value for the entry
  const organicFlex = interpolate(
    flexIn, 
    [0, 1], 
    [0, 1]
  );
  
  // Final swell value calculation
  // When 'flexAmount' is 1, we are fully flexed. 
  // We use the spring 'flexIn' for the entry to make it bouncy, 
  // and simple interpolation for the exit or a second spring.
  // Let's keep it simple: Use the interpolated frame value to drive the height,
  // but mix in the spring for the "hit".
  
  const currentSwell = interpolate(
    frame,
    [flexStartFrame, flexStartFrame + flexDuration],
    [0, swellingIntensity],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: (t) => t } // Linear base
  );

  // Let's actually use the spring for the 'swell' to give it muscle physics
  const swellValue = interpolate(
    frame,
    [0, flexStartFrame, flexStartFrame + flexDuration, relaxStartFrame, relaxStartFrame + flexDuration * 1.5],
    [0, 0, swellingIntensity, swellingIntensity, 0],
    { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }
  );
  
  // Add a little over-shoot bounce on the flex-in
  const bounce = spring({
    frame: frame - flexStartFrame,
    fps,
    config: { stiffness: 150, damping: 10 }
  });
  
  // Composite swell: 
  // If before relax phase, use bounce * intensity
  // If after relax phase, use linear interpolate out
  const isRelaxing = frame > relaxStartFrame;
  
  const finalSwell = isRelaxing 
    ? interpolate(frame, [relaxStartFrame, relaxStartFrame + flexDuration], [swellingIntensity, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" })
    : interpolate(bounce, [0, 1], [0, swellingIntensity]);


  // SVG Path Construction
  // ViewBox 0 0 200 200
  // Arm is constructed to fit within ~120x120 area
  
  const startX = 160;
  const startY = 150; // Bottom of tricep/shoulder connection
  const shoulderX = 160;
  const shoulderY = 100; // Top of shoulder

  // Dynamic Control Point for Bicep
  // The bicep connects (80, 100) [Inner Elbow] to (160, 100) [Shoulder]
  // Midpoint approx (120, 100). We move Y upwards to swell.
  const bicepControlY = 100 - finalSwell; 

  const armPath = `
    M ${startX} ${startY} 
    L 60 150 
    Q 40 150 40 130 
    L 50 30 
    Q 50 20 70 20
    L 90 20
    Q 100 20 100 40
    L 90 40
    L 80 100 
    Q 120 ${bicepControlY} ${shoulderX} ${shoulderY}
    L ${startX} ${startY}
    Z
  `;

  // Graph Path Construction
  const graphPath = `
    M 10 90
    L 30 70
    L 50 85
    L 80 40
    L 100 60
    L 140 10
  `;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <AbsoluteFill style={{ 
        display: 'flex', 
        flexDirection: 'row', 
        justifyContent: 'center', 
        alignItems: 'center',
        gap: 40 * iconScale
      }}>
        
        {/* BICEP ICON */}
        <div style={{ 
          width: 200 * iconScale, 
          height: 200 * iconScale, 
          position: 'relative',
        }}>
           <svg 
            viewBox="0 0 200 200" 
            style={{ 
              width: '100%', 
              height: '100%', 
              overflow: 'visible',
              transform: 'rotate(-5deg)' // Slight natural tilt
            }}
          >
             {/* Arm Shape */}
             <path 
               d={armPath}
               fill={skinColor}
               stroke={outlineColor}
               strokeWidth={6}
               strokeLinecap="round"
               strokeLinejoin="round"
               style={{ transition: 'none' }} // Crucial for frame-by-frame interpolation
             />
             
             {/* Detail: Inner Elbow Crease */}
             <path 
                d="M 80 100 Q 90 110 100 100"
                fill="none"
                stroke={outlineColor}
                strokeWidth={3}
                strokeOpacity={0.3}
                strokeLinecap="round"
             />
           </svg>
        </div>

        {/* MARKET GRAPH ICON */}
        <div style={{ 
          width: 150 * iconScale, 
          height: 150 * iconScale,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}>
           <svg viewBox="0 0 150 100" style={{ width: '100%', height: '100%', overflow: 'visible' }}>
             {/* Axes */}
             <line x1="10" y1="10" x2="10" y2="90" stroke={outlineColor} strokeWidth={4} strokeLinecap="round" />
             <line x1="10" y1="90" x2="140" y2="90" stroke={outlineColor} strokeWidth={4} strokeLinecap="round" />
             
             {/* Trend Line */}
             <path 
               d={graphPath}
               fill="none"
               stroke={graphColor}
               strokeWidth={6}
               strokeLinecap="round"
               strokeLinejoin="round"
             />
             
             {/* Arrow Head */}
             <path
               d="M 130 10 L 140 10 L 140 25"
               fill="none"
               stroke={graphColor}
               strokeWidth={6}
               strokeLinecap="round"
               strokeLinejoin="round"
             />
           </svg>
        </div>

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default FlexBicepGraph;